    "app.engineTuning.delegationHelp": "Розподіл роботи між допоміжними агентами. Виклики інструментів у межах одного ходу завжди виконуються послідовно; лише делегування дає Jenny змогу працювати паралельно.",
    "app.engineTuning.maxBudgetUsdHelp": "Зупинити відповідь, коли вартість цього ходу в постачальника перевищить указану суму. Залиште поле порожнім, щоб не обмежувати витрати.",
    "app.engineTuning.maxChatLoopIterationsHelp": "Скільки разів Jenny може знову зупинитися й обміркувати відповідь після виконання інструментів у звичайному чаті.",
    "app.engineTuning.maxCloudSubAgentConcurrencyHelp": "Скільки делегованих допоміжних завдань може одночасно виконувати хмарна модель. Планувальник обмежує це значення до 3.",
    "app.engineTuning.maxCodeIntelligenceToolCallsPerTurnHelp": "Скільки викликів інструментів аналізу коду може використати одна відповідь.",
    "app.engineTuning.maxInlinePayloadBytesHelp": "Результат інструмента, більший за це значення, буде збережено у файлі з посиланням замість вставлення в розмову.",
    "app.engineTuning.maxLoopIterationsHelp": "Використовується лише тоді, коли контроль ресурсів вимкнено. Також задає початкове обмеження для чату, якщо його не вказано окремо.",
    "app.engineTuning.maxLoopWallSecondsHelp": "Скільки часу локальний хід може активно виконувати роботу. Час очікування на ваше схвалення або відповіді до цього обмеження не зараховується.",
    "app.engineTuning.maxSubAgentConcurrencyHelp": "Скільки делегованих допоміжних завдань може одночасно виконувати локальна модель. Значення 1 означає послідовне виконання.",
    "app.engineTuning.maxSubAgentLoopIterationsHelp": "Скільки циклів міркування отримує кожне допоміжне завдання. Значення навмисно однакове для локальної та хмарної моделей: для більшої роботи слід залучити більше помічників, а не подовжувати їхню роботу.",
    "app.engineTuning.maxTaskLoopIterationsHelp": "Таке саме обмеження для режиму завдань, розрахованого на тривалішу багатоетапну роботу.",
