    "app.engineTuning.maxToolsPerTurnHelp": "Скільки викликів інструментів (читання файлів, пошуків в Інтернеті тощо) може зробити Jenny, відповідаючи на одне повідомлення. Збільште значення для тривалих завдань із багатьма інструментами або зменште для швидших відповідей.",
    "app.engineTuning.maxWebToolCallsPerTurnHelp": "Скільки пошуків в Інтернеті або завантажень сторінок може використати одна відповідь. Ураховуються лише успішні виклики; невдалі не витрачають ліміт.",
    "app.engineTuning.modelLoadGraceSecondsHelp": "Скільки чекати на перші слова, поки локальна модель завантажується в пам’ять графічного процесора. Збільште значення для дуже великих моделей або повільних дисків.",
